CREATE TABLE public.ppm_usuarios (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ppm_usuarios TO authenticated; GRANT ALL ON public.ppm_usuarios TO service_role;
ALTER TABLE public.ppm_usuarios ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ppm_papeis (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), papel text NOT NULL CHECK (papel IN ('tecnico','gestor','alta_administracao','administrador_pmo','auditor','ai_owner')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,papel));
GRANT SELECT ON public.ppm_papeis TO authenticated; GRANT ALL ON public.ppm_papeis TO service_role;
ALTER TABLE public.ppm_papeis ENABLE ROW LEVEL SECURITY;
INSERT INTO public.profiles(id,email,display_name) SELECT u.id,coalesce(u.email,''),coalesce(u.raw_user_meta_data->>'display_name',split_part(coalesce(u.email,''),'@',1)) FROM auth.users u ON CONFLICT(id) DO NOTHING;
INSERT INTO public.ppm_usuarios(user_id) SELECT id FROM public.profiles;
INSERT INTO public.ppm_papeis(user_id,papel) SELECT user_id,'administrador_pmo' FROM public.user_roles WHERE role='superadmin' ON CONFLICT DO NOTHING;
INSERT INTO public.ppm_papeis(user_id,papel) SELECT updated_by,'ai_owner' FROM public.app_settings WHERE id='ai' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.ppm_ativo() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.ppm_usuarios WHERE user_id=auth.uid() AND ativo) $$;
CREATE FUNCTION public.ppm_tem_papel(p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.ppm_ativo() AND EXISTS(SELECT 1 FROM public.ppm_papeis WHERE user_id=auth.uid() AND papel=p) $$;
REVOKE ALL ON FUNCTION public.ppm_ativo(), public.ppm_tem_papel(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_ativo(), public.ppm_tem_papel(text) TO authenticated,service_role;
CREATE POLICY ppm_users_read ON public.ppm_usuarios FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.ppm_tem_papel('administrador_pmo'));
CREATE POLICY ppm_roles_read ON public.ppm_papeis FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.ppm_tem_papel('administrador_pmo'));
CREATE POLICY ppm_profiles_directory ON public.profiles FOR SELECT TO authenticated USING (public.ppm_tem_papel('administrador_pmo'));
DROP POLICY IF EXISTS "Authorized demo superadmin can claim role" ON public.user_roles;
REVOKE INSERT ON public.user_roles FROM authenticated;
CREATE TABLE public.areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, sigla text NOT NULL, responsavel text NOT NULL DEFAULT '', responsavel_id uuid REFERENCES public.profiles(id), visibilidade text NOT NULL DEFAULT 'Restrita' CHECK(visibilidade IN ('Aberta','Restrita')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.areas TO authenticated; GRANT ALL ON public.areas TO service_role;
ALTER TABLE public.areas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.area_membros (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id uuid NOT NULL REFERENCES public.areas(id), usuario_id uuid NOT NULL REFERENCES public.profiles(id), papel text NOT NULL DEFAULT 'Membro' CHECK(papel IN ('Membro','Dono da área')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid(), UNIQUE(area_id,usuario_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.area_membros TO authenticated; GRANT ALL ON public.area_membros TO service_role;
ALTER TABLE public.area_membros ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.ppm_membro(a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.ppm_ativo() AND EXISTS(SELECT 1 FROM public.area_membros WHERE area_id=a AND usuario_id=auth.uid()) $$;
CREATE FUNCTION public.ppm_ver_area(a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.ppm_ativo() AND (public.ppm_tem_papel('administrador_pmo') OR public.ppm_tem_papel('alta_administracao') OR public.ppm_tem_papel('auditor') OR public.ppm_membro(a) OR EXISTS(SELECT 1 FROM public.areas WHERE id=a AND visibilidade='Aberta')) $$;
REVOKE ALL ON FUNCTION public.ppm_membro(uuid),public.ppm_ver_area(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_membro(uuid),public.ppm_ver_area(uuid) TO authenticated,service_role;
CREATE POLICY areas_read ON public.areas FOR SELECT TO authenticated USING(public.ppm_ver_area(id));
CREATE POLICY areas_write ON public.areas FOR ALL TO authenticated USING(public.ppm_tem_papel('administrador_pmo')) WITH CHECK(public.ppm_tem_papel('administrador_pmo'));
CREATE POLICY membros_read ON public.area_membros FOR SELECT TO authenticated USING(public.ppm_ver_area(area_id));
CREATE POLICY membros_write ON public.area_membros FOR ALL TO authenticated USING(public.ppm_tem_papel('administrador_pmo')) WITH CHECK(public.ppm_tem_papel('administrador_pmo'));
CREATE TABLE public.objetos_acesso (id uuid PRIMARY KEY, tipo text NOT NULL, parent_id uuid REFERENCES public.objetos_acesso(id), area_id uuid NOT NULL REFERENCES public.areas(id), visibilidade text NOT NULL DEFAULT 'publica' CHECK(visibilidade IN ('publica','compartilhada','privada')), responsavel_id uuid REFERENCES public.profiles(id), compartilhado_com uuid[] NOT NULL DEFAULT '{}', convidados jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT ON public.objetos_acesso TO authenticated; GRANT ALL ON public.objetos_acesso TO service_role;
ALTER TABLE public.objetos_acesso ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.ppm_pode_ver(o uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.objetos_acesso; BEGIN IF NOT public.ppm_ativo() THEN RETURN false; END IF; SELECT * INTO r FROM public.objetos_acesso WHERE id=o; IF NOT FOUND THEN RETURN false; END IF; IF public.ppm_tem_papel('administrador_pmo') OR public.ppm_tem_papel('alta_administracao') OR public.ppm_tem_papel('auditor') THEN RETURN true; END IF; IF r.parent_id IS NOT NULL AND NOT public.ppm_pode_ver(r.parent_id) THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(r.convidados) c WHERE c->>'usuarioId'=auth.uid()::text) THEN RETURN true; END IF; IF r.visibilidade='privada' THEN RETURN false; END IF; IF public.ppm_membro(r.area_id) THEN RETURN true; END IF; IF r.visibilidade='compartilhada' THEN RETURN EXISTS(SELECT 1 FROM public.area_membros WHERE usuario_id=auth.uid() AND area_id=ANY(r.compartilhado_com)); END IF; RETURN public.ppm_ver_area(r.area_id); END $$;
CREATE FUNCTION public.ppm_pode_editar(o uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.objetos_acesso; n text; BEGIN IF NOT public.ppm_pode_ver(o) THEN RETURN false; END IF; IF public.ppm_tem_papel('administrador_pmo') THEN RETURN true; END IF; IF public.ppm_tem_papel('auditor') OR public.ppm_tem_papel('alta_administracao') THEN RETURN false; END IF; SELECT * INTO r FROM public.objetos_acesso WHERE id=o; IF public.ppm_tem_papel('tecnico') THEN RETURN r.responsavel_id=auth.uid() AND public.ppm_membro(r.area_id); END IF; IF public.ppm_tem_papel('gestor') THEN IF public.ppm_membro(r.area_id) THEN RETURN true; END IF; SELECT c->>'nivel' INTO n FROM jsonb_array_elements(r.convidados)c WHERE c->>'usuarioId'=auth.uid()::text; RETURN coalesce(n IN ('Editar tudo','Editar conteúdo'),false); END IF; RETURN false; END $$;
REVOKE ALL ON FUNCTION public.ppm_pode_ver(uuid),public.ppm_pode_editar(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_pode_ver(uuid),public.ppm_pode_editar(uuid) TO authenticated,service_role;
CREATE POLICY objetos_read ON public.objetos_acesso FOR SELECT TO authenticated USING(public.ppm_pode_ver(id));
CREATE TABLE public.portfolios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id uuid NOT NULL REFERENCES public.areas(id), nome text NOT NULL, tipo text NOT NULL DEFAULT 'Institucional', responsavel text NOT NULL DEFAULT '', responsavel_id uuid REFERENCES public.profiles(id), orcamento numeric NOT NULL DEFAULT 0 CHECK(orcamento>=0), prioridade integer NOT NULL DEFAULT 1, score numeric NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), saude text NOT NULL DEFAULT 'verde', status text NOT NULL DEFAULT 'Ativo', data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
