GRANT SELECT,INSERT,UPDATE,DELETE ON public.programas TO authenticated; GRANT ALL ON public.programas TO service_role;
ALTER TABLE public.programas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.projetos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), programa_id uuid NOT NULL REFERENCES public.programas(id), nome text NOT NULL, gerente text NOT NULL DEFAULT '', gerente_id uuid REFERENCES public.profiles(id), metodologia text NOT NULL DEFAULT 'PMBOK', status text NOT NULL DEFAULT 'Planejamento', inicio date, fim date, orcamento numeric NOT NULL DEFAULT 0 CHECK(orcamento>=0), executado numeric NOT NULL DEFAULT 0 CHECK(executado>=0), progresso numeric NOT NULL DEFAULT 0 CHECK(progresso BETWEEN 0 AND 100), saude text NOT NULL DEFAULT 'verde', escopo text NOT NULL DEFAULT '', criterios_aceite text NOT NULL DEFAULT '', data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid(), CHECK(fim IS NULL OR inicio IS NULL OR fim>=inicio));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.projetos TO authenticated; GRANT ALL ON public.projetos TO service_role;
ALTER TABLE public.projetos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.objetivos_estrategicos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id uuid NOT NULL REFERENCES public.areas(id), codigo text NOT NULL, nome text NOT NULL, perspectiva text NOT NULL DEFAULT '', meta text NOT NULL DEFAULT '', responsavel text NOT NULL DEFAULT '', responsavel_id uuid REFERENCES public.profiles(id), prazo date, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.objetivos_estrategicos TO authenticated; GRANT ALL ON public.objetivos_estrategicos TO service_role;
ALTER TABLE public.objetivos_estrategicos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.indicadores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id uuid NOT NULL REFERENCES public.areas(id), nome text NOT NULL, formula text NOT NULL DEFAULT '', unidade text NOT NULL DEFAULT '', meta numeric NOT NULL DEFAULT 0, polaridade text NOT NULL DEFAULT 'maior', periodicidade text NOT NULL DEFAULT 'Mensal', responsavel text NOT NULL DEFAULT '', responsavel_id uuid REFERENCES public.profiles(id), nivel text NOT NULL DEFAULT 'institucional', calculo text, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.indicadores TO authenticated; GRANT ALL ON public.indicadores TO service_role;
ALTER TABLE public.indicadores ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.riscos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), area_id uuid NOT NULL REFERENCES public.areas(id), origem_id uuid REFERENCES public.objetos_acesso(id), nome text NOT NULL, categoria text NOT NULL DEFAULT 'Projeto', origem text NOT NULL DEFAULT '', probabilidade integer NOT NULL DEFAULT 1 CHECK(probabilidade BETWEEN 1 AND 5), impacto integer NOT NULL DEFAULT 1 CHECK(impacto BETWEEN 1 AND 5), severidade integer GENERATED ALWAYS AS (probabilidade*impacto) STORED, resposta text NOT NULL DEFAULT 'Mitigar', tendencia text NOT NULL DEFAULT 'estável', responsavel text NOT NULL DEFAULT '', responsavel_id uuid REFERENCES public.profiles(id), prazo date, status text NOT NULL DEFAULT 'Aberto', data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.riscos TO authenticated; GRANT ALL ON public.riscos TO service_role;
ALTER TABLE public.riscos ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.ppm_registrar_objeto() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid; p uuid; r uuid; t text; BEGIN t:=TG_TABLE_NAME; IF t='portfolios' THEN a:=NEW.area_id; r:=NEW.responsavel_id; ELSIF t='programas' THEN p:=NEW.portfolio_id; SELECT area_id INTO a FROM public.objetos_acesso WHERE id=p; r:=NEW.gerente_id; ELSIF t='projetos' THEN p:=NEW.programa_id; SELECT area_id INTO a FROM public.objetos_acesso WHERE id=p; r:=NEW.gerente_id; ELSIF t='riscos' THEN a:=NEW.area_id; p:=NEW.origem_id; r:=NEW.responsavel_id; ELSE a:=NEW.area_id; r:=NEW.responsavel_id; END IF; IF TG_OP='UPDATE' AND (SELECT parent_id IS DISTINCT FROM p OR area_id IS DISTINCT FROM a FROM public.objetos_acesso WHERE id=NEW.id) AND NOT public.ppm_tem_papel('administrador_pmo') AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Somente Administrador/PMO pode mover registros entre áreas'; END IF; INSERT INTO public.objetos_acesso(id,tipo,parent_id,area_id,responsavel_id) VALUES(NEW.id,t,p,a,r) ON CONFLICT(id) DO UPDATE SET parent_id=excluded.parent_id,area_id=excluded.area_id,responsavel_id=excluded.responsavel_id; RETURN NEW; END $$;
CREATE FUNCTION public.ppm_carimbar() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at:=now(); NEW.updated_by:=auth.uid(); IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['portfolios','programas','projetos','objetivos_estrategicos','indicadores','riscos'] LOOP EXECUTE format('CREATE TRIGGER ppm_registry BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.ppm_registrar_objeto()',t); EXECUTE format('CREATE POLICY ppm_read ON public.%I FOR SELECT TO authenticated USING(public.ppm_pode_ver(id))',t); EXECUTE format('CREATE POLICY ppm_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(public.ppm_pode_editar(id))',t); EXECUTE format('CREATE POLICY ppm_update ON public.%I FOR UPDATE TO authenticated USING(public.ppm_pode_editar(id)) WITH CHECK(public.ppm_pode_editar(id))',t); EXECUTE format('CREATE POLICY ppm_delete ON public.%I FOR DELETE TO authenticated USING(public.ppm_tem_papel(''administrador_pmo''))',t); END LOOP; END $$;
