GRANT SELECT,INSERT ON public.projeto_atualizacoes TO authenticated; GRANT ALL ON public.projeto_atualizacoes TO service_role; ALTER TABLE public.projeto_atualizacoes ENABLE ROW LEVEL SECURITY;
