GRANT SELECT,INSERT,UPDATE,DELETE ON public.metas_estrategicas TO authenticated; GRANT ALL ON public.metas_estrategicas TO service_role; ALTER TABLE public.metas_estrategicas ENABLE ROW LEVEL SECURITY;
