GRANT SELECT,INSERT,UPDATE,DELETE ON public.alinhamento_estrategico TO authenticated; GRANT ALL ON public.alinhamento_estrategico TO service_role; ALTER TABLE public.alinhamento_estrategico ENABLE ROW LEVEL SECURITY;
