GRANT SELECT,INSERT,UPDATE,DELETE ON public.risco_planos TO authenticated; GRANT ALL ON public.risco_planos TO service_role; ALTER TABLE public.risco_planos ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.ppm_editar_filho(p uuid,r uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.ppm_pode_ver(p) AND CASE WHEN public.ppm_tem_papel('auditor') OR public.ppm_tem_papel('alta_administracao') THEN false WHEN public.ppm_tem_papel('administrador_pmo') THEN true WHEN public.ppm_tem_papel('tecnico') THEN r=auth.uid() AND public.ppm_membro((SELECT area_id FROM public.objetos_acesso WHERE id=p)) ELSE public.ppm_pode_editar(p) END $$;
REVOKE ALL ON FUNCTION public.ppm_editar_filho(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.ppm_editar_filho(uuid,uuid) TO authenticated,service_role;
DO $$ DECLARE t text; c text; w text; BEGIN FOR t,c IN SELECT * FROM (VALUES ('programa_metas','programa_id'),('projeto_elementos','projeto_id'),('projeto_subelementos','projeto_id'),('projeto_atualizacoes','projeto_id'),('projeto_tarefas','projeto_id'),('status_reports','projeto_id'),('metas_estrategicas','objetivo_id'),('iniciativas','objetivo_id'),('alinhamento_estrategico','objetivo_id'),('indicador_valores','indicador_id'),('risco_planos','risco_id'))v LOOP w:=format('public.ppm_pode_editar(%I)',c); IF t IN ('projeto_elementos','projeto_subelementos','projeto_tarefas') THEN w:=format('public.ppm_editar_filho(%I,responsavel_id)',c); END IF; IF t='alinhamento_estrategico' THEN w:=w||' AND public.ppm_pode_ver(objeto_id)'; END IF; EXECUTE format('CREATE POLICY ppm_read ON public.%I FOR SELECT TO authenticated USING(public.ppm_pode_ver(%I)%s)',t,c,CASE WHEN t='alinhamento_estrategico' THEN ' AND public.ppm_pode_ver(objeto_id)' ELSE '' END); EXECUTE format('CREATE POLICY ppm_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(%s)',t,w); IF t<>'projeto_atualizacoes' THEN EXECUTE format('CREATE POLICY ppm_update ON public.%I FOR UPDATE TO authenticated USING(%s) WITH CHECK(%s)',t,w,w); EXECUTE format('CREATE POLICY ppm_delete ON public.%I FOR DELETE TO authenticated USING(public.ppm_tem_papel(''administrador_pmo''))',t); END IF; EXECUTE format('CREATE INDEX ON public.%I(%I,created_at DESC)',t,c); END LOOP; END $$;
CREATE TABLE public.views_usuario (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), nome text NOT NULL, escopo text NOT NULL CHECK(escopo IN ('executiva','indicadores')), blocos text[] NOT NULL DEFAULT '{}', perfis text[] NOT NULL DEFAULT '{}', areas uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.views_usuario TO authenticated; GRANT ALL ON public.views_usuario TO service_role; ALTER TABLE public.views_usuario ENABLE ROW LEVEL SECURITY;
CREATE POLICY views_owner ON public.views_usuario FOR ALL TO authenticated USING(public.ppm_ativo() AND user_id=auth.uid()) WITH CHECK(public.ppm_ativo() AND user_id=auth.uid());
CREATE TABLE public.etiquetas_carteira (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), coluna text NOT NULL CHECK(coluna IN ('tipo','metodologia','status')), nome text NOT NULL, tom text NOT NULL DEFAULT 'cinza', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid(), UNIQUE(coluna,nome));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.etiquetas_carteira TO authenticated; GRANT ALL ON public.etiquetas_carteira TO service_role; ALTER TABLE public.etiquetas_carteira ENABLE ROW LEVEL SECURITY;
CREATE POLICY etiquetas_read ON public.etiquetas_carteira FOR SELECT TO authenticated USING(public.ppm_ativo()); CREATE POLICY etiquetas_write ON public.etiquetas_carteira FOR ALL TO authenticated USING(public.ppm_tem_papel('administrador_pmo')) WITH CHECK(public.ppm_tem_papel('administrador_pmo'));
CREATE VIEW public.totais_programa WITH(security_invoker=true) AS SELECT g.id, count(p.id)::integer projetos, coalesce(sum(p.orcamento),0) orcamento,coalesce(sum(p.executado),0) executado,coalesce(round(avg(p.progresso),2),0) progresso FROM public.programas g LEFT JOIN public.projetos p ON p.programa_id=g.id GROUP BY g.id;
CREATE VIEW public.totais_portfolio WITH(security_invoker=true) AS SELECT f.id,(SELECT count(*)::integer FROM public.programas g WHERE g.portfolio_id=f.id) programas, count(p.id)::integer projetos, coalesce(sum(p.orcamento),0) orcamento_projetos,coalesce(sum(p.executado),0) executado,coalesce(round(avg(p.progresso),2),0) progresso,(SELECT count(*)::integer FROM public.riscos r JOIN public.objetos_acesso o ON o.id=r.origem_id WHERE r.severidade>=15 AND (o.id=f.id OR o.parent_id=f.id OR o.parent_id IN (SELECT id FROM public.programas WHERE portfolio_id=f.id))) riscos_criticos FROM public.portfolios f LEFT JOIN public.programas g ON g.portfolio_id=f.id LEFT JOIN public.projetos p ON p.programa_id=g.id GROUP BY f.id;
CREATE VIEW public.totais_institucionais WITH(security_invoker=true) AS SELECT (SELECT count(*)::integer FROM public.portfolios) portfolios,(SELECT count(*)::integer FROM public.programas) programas,count(*)::integer projetos,coalesce(sum(orcamento),0) orcamento,coalesce(sum(executado),0) executado,coalesce(round(avg(progresso),2),0) progresso,(SELECT count(*)::integer FROM public.riscos WHERE severidade>=15) riscos_criticos FROM public.projetos;
GRANT SELECT ON public.totais_programa,public.totais_portfolio,public.totais_institucionais TO authenticated,service_role;
CREATE INDEX ON public.portfolios(area_id,created_at DESC); CREATE INDEX ON public.programas(portfolio_id,created_at DESC); CREATE INDEX ON public.projetos(programa_id,status,created_at DESC); CREATE INDEX ON public.riscos(area_id,severidade,created_at DESC); CREATE INDEX ON public.objetos_acesso(parent_id); CREATE INDEX ON public.area_membros(usuario_id,area_id);
CREATE INDEX IF NOT EXISTS security_audit_user_time ON public.security_audit_log(user_id,created_at DESC);
CREATE FUNCTION public.ppm_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.security_audit_log(user_id,event_type,entity_type,entity_id,result,context) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id'),'success',jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END)); END IF; RETURN coalesce(NEW,OLD); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['areas','area_membros','portfolios','programas','projetos','objetivos_estrategicos','indicadores','riscos','programa_metas','projeto_elementos','projeto_subelementos','projeto_atualizacoes','projeto_tarefas','status_reports','metas_estrategicas','iniciativas','alinhamento_estrategico','indicador_valores','risco_planos','views_usuario','etiquetas_carteira'] LOOP EXECUTE format('CREATE TRIGGER ppm_stamp BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.ppm_carimbar()',t); EXECUTE format('CREATE TRIGGER ppm_audit AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.ppm_auditar()',t); END LOOP; END $$;
DROP POLICY IF EXISTS "Designated security owner can read all audit events" ON public.security_audit_log;
CREATE POLICY ppm_auditors_read ON public.security_audit_log FOR SELECT TO authenticated USING(public.ppm_tem_papel('administrador_pmo') OR public.ppm_tem_papel('auditor'));
DROP POLICY IF EXISTS "Superadmins can create application settings" ON public.app_settings; DROP POLICY IF EXISTS "Superadmins can update application settings" ON public.app_settings;
CREATE POLICY ppm_ai_create ON public.app_settings FOR INSERT TO authenticated WITH CHECK(id='ai' AND updated_by=auth.uid() AND public.ppm_tem_papel('ai_owner'));
CREATE POLICY ppm_ai_update ON public.app_settings FOR UPDATE TO authenticated USING(id='ai' AND public.ppm_tem_papel('ai_owner')) WITH CHECK(id='ai' AND updated_by=auth.uid() AND public.ppm_tem_papel('ai_owner'));
CREATE POLICY ppm_ai_read ON public.app_settings FOR SELECT TO authenticated USING(id='ai' AND public.ppm_ativo());
ALTER PUBLICATION supabase_realtime ADD TABLE public.portfolios,public.programas,public.projetos,public.riscos,public.indicadores,public.indicador_valores,public.status_reports,public.projeto_elementos,public.projeto_subelementos,public.projeto_atualizacoes,public.areas,public.area_membros,public.objetos_acesso,public.views_usuario;
COMMENT ON TABLE public.ppm_papeis IS 'Protected application roles and explicit capabilities. Profiles never confer privileges.';